{'code': "from qgis.PyQt.QtWidgets import QAction, QToolBar
mw = iface.mainWindow()
action = mw.findChild(QAction, 'mActionToggleDatabaseToolBar')
if action is None:
    cands = [(a.objectName(), a.text(), a.isCheckable(), a.isChecked() if a.isCheckable() else None) for a in mw.findChildren(QAction) if 'データベース' in a.text() or 'atabase' in (a.objectName() or '')]
    result = {'action': None, 'candidates': cands}
else:
    action.trigger()
    tb = mw.findChild(QToolBar, 'mDatabaseToolBar')
    result = {'action': action.objectName(), 'checked': action.isChecked(), 'toolbar_visible': tb.isVisible() if tb else None}"}
